1	import assert from "node:assert/strict";
2	import { describe, test } from "node:test";
3	import { manifestTeu, reeferCount, teuOf, verifiedGrossMassTonnes } from "@harbor/dispatch/cargo/manifest";
4	import type { Container } from "@harbor/dispatch/types";
5	
6	const box = (id: string, lengthFt: 20 | 40 | 45, extra: Partial<Container> = {}): Container => ({
7	  id,
8	  lengthFt,
9	  cargoKg: 10_000,
10	  tareKg: 0,
11	  ...extra,
12	});
13	
14	describe("manifest", () => {
15	  test("twenty and forty foot boxes", () => {
16	    assert.equal(teuOf(box("A", 20)), 1);
17	    assert.equal(teuOf(box("B", 40)), 2);
18	    assert.equal(manifestTeu([box("A", 20), box("B", 40), box("C", 20)]), 4);
19	  });
20	
21	  test("unknown lengths are rejected", () => {
22	    assert.throws(() => teuOf({ ...box("X", 20), lengthFt: 30 as unknown as 20 }), RangeError);
23	  });
24	
25	  test("mass is reported in tonnes", () => {
26	    assert.equal(verifiedGrossMassTonnes(box("A", 20, { cargoKg: 12_000 })), 12);
27	    assert.throws(() => verifiedGrossMassTonnes(box("A", 20, { cargoKg: -1 })), RangeError);
28	  });
29	
30	  test("reefers are counted", () => {
31	    assert.equal(reeferCount([box("A", 40, { reefer: true }), box("B", 40), box("C", 20, { reefer: true })]), 2);
32	  });
33	});
